const item = $input.first().json;
const body = item.body || item;

// The actual on/off toggle lives in GHL (an If/Else branch decides which
// contacts even reach the "Add Tag" + Webhook steps upstream) - GHL's tags
// merge field doesn't reliably serialize into a webhook JSON body, so this
// step isn't a tag check. It's just a sanity check that we got a contact to
// post a note to and a business to research at all.
if (!body.contactId || !body.businessName) {
  return [];
}

return [{ json: body }];

const lead = $input.first().json;

const businessName = lead.businessName || lead.business_name || "";
const city = lead.city || "";
const state = lead.state || "";
const location = [city, state].filter(Boolean).join(", ");
const contactName = [lead.firstName, lead.lastName].filter(Boolean).join(" ") || lead.contactName || "";

if (!businessName) {
  // Not enough to research - stop rather than post a note with nothing behind it.
  return [];
}

const searchQuery = `${businessName} ${location} auto body shop`.trim();

return [{
  json: {
    ...lead,
    location,
    contactName,
    searchQuery,
  },
}];

const lead = $('Build Search Query').first().json;
const serp = $input.first().json;

const organic = serp.organic_results || [];
const local = (serp.local_results && serp.local_results.places) || [];

const results = [];

for (const r of local.slice(0, 5)) {
  results.push({
    title: r.title || "",
    link: r.link || r.website || "",
    snippet: [r.address, r.rating ? `Rating: ${r.rating} (${r.reviews || 0} reviews)` : ""]
      .filter(Boolean)
      .join(" \u2014 "),
  });
}

for (const r of organic.slice(0, 10)) {
  results.push({
    title: r.title || "",
    link: r.link || "",
    snippet: r.snippet || "",
  });
}

const deduped = [];
const seen = new Set();
for (const r of results) {
  if (!r.link || seen.has(r.link)) continue;
  seen.add(r.link);
  deduped.push(r);
}
const top10 = deduped.slice(0, 10);

const numbered = top10
  .map((r, i) => `${i + 1}. ${r.title}\n   ${r.link}\n   "${r.snippet}"`)
  .join("\n\n");

return [{
  json: {
    ...lead,
    searchResults: top10,
    numberedSearchResults: numbered || "No search results were returned.",
  },
}];

const lead = $input.first().json;

const userPrompt = [
  `I'm researching a business for lead qualification before a sales call.`,
  `Business name: ${lead.businessName || ""}`,
  `Location (if known): ${lead.location || ""}`,
  ``,
  `Here are the top search results:`,
  ``,
  lead.numberedSearchResults,
  ``,
  `Which of these links are worth opening for the most valuable information about this business? Prioritize: official website, Google Business profile, LinkedIn company page, relevant local business directories. Skip: news articles, review sites, unrelated social media, aggregator sites with no unique info.`,
  ``,
  `Respond with a JSON array of the links worth opening, most valuable first. Each item must be {"url": "...", "title": "..."}. Include at most 5 items. If none are worth opening, respond with an empty array: []`,
].join("\n");

return [{
  json: {
    ...lead,
    claudeRequestBody: {
      model: "claude-haiku-4-5-20251001",
      max_tokens: 600,
      system: "You are helping filter search results before a sales call. Respond ONLY with valid JSON. No prose, no markdown fences, no explanation outside the JSON.",
      messages: [{ role: "user", content: userPrompt }],
    },
  },
}];

const lead = $('Parse SerpAPI Results').first().json;
const claudeResponse = $input.first().json;

let flagged = [];
try {
  const text = (claudeResponse.content && claudeResponse.content[0] && claudeResponse.content[0].text) || "[]";
  const parsed = JSON.parse(text);
  if (Array.isArray(parsed)) {
    flagged = parsed
      .filter((item) => item && typeof item.url === "string")
      .slice(0, 5);
  }
} catch (err) {
  // Filtering failed or returned something unparseable - degrade gracefully.
  // Synthesis still runs on the search snippets alone.
  flagged = [];
}

return [{
  json: {
    ...lead,
    flaggedLinks: flagged,
  },
}];

const lead = $('Parse SerpAPI Results').first().json;
const scraped = $input.all().map((item) => item.json).filter((s) => s && s.success && s.text);

const searchSnippets = (lead.searchResults || [])
  .map((r, i) => `${i + 1}. ${r.title}\n   ${r.link}\n   "${r.snippet}"`)
  .join("\n\n") || "No search results were returned.";

const scrapedContent = scraped.length
  ? scraped
      .map((s) => `### ${s.title || s.url} (${s.url})\n${s.text}`)
      .join("\n\n---\n\n")
  : "";

const noScrapedContent = scraped.length === 0;
const locationLine = lead.location ? ` in ${lead.location}` : "";
const contactLine = lead.contactName ? `The lead form was submitted by: ${lead.contactName}` : "";

const userPrompt = [
  `You are preparing a quick, actionable call-prep brief for a sales rep about to call a potential customer - often while they're out in the field, so this needs to be scannable in about 15 seconds, not read like a memo. Here is what we found about ${lead.businessName}${locationLine}: search result snippets, and full scraped content from their website and other pages where available.`,
  contactLine,
  ``,
  `SEARCH RESULT SNIPPETS:`,
  searchSnippets,
  ``,
  `SCRAPED PAGE CONTENT:`,
  noScrapedContent
    ? `(No pages were flagged as high-value enough to open, or the pages that were flagged failed to load. Work only from the search snippets above, and say plainly that deeper research wasn't available.)`
    : scrapedContent,
  ``,
  `Write the brief in exactly this structure:`,
  ``,
  `**Quick facts:**`,
  `- Website: [the actual URL from the material above, only if you're confident it's their real official site - otherwise write "Not found"]`,
  `- Google Business Profile: [the actual URL from the material above if one appears, otherwise "Not found"]`,
  `- Google rating: [e.g. "4.6 stars (128 reviews)" if a rating/review count appears in the material above, otherwise "Not found"]`,
  `- Location: [city/state - flag in a few words if sources disagree]`,
  `- Decision maker: [name if found online; otherwise the lead form contact name if that's all you have]`,
  `- Years in business: [if found, otherwise "Not found"]`,
  ``,
  `**What to know before you dial:** 2-3 short sentences (not paragraphs) covering website quality, any recent news, and the single most important discrepancy between sources if one exists - state plainly which source you lean toward trusting and why. Skip anything not found rather than padding with filler.`,
  ``,
  `Be honest and specific. Never invent a URL, rating, or name that isn't explicitly present in the search snippets or scraped content above - write "Not found" instead of guessing.`,
].filter(Boolean).join("\n");

return [{
  json: {
    contactId: lead.contactId,
    businessName: lead.businessName,
    claudeRequestBody: {
      model: "claude-sonnet-5",
      max_tokens: 900,
      messages: [{ role: "user", content: userPrompt }],
    },
  },
}];

const lead = $('Build Claude Synthesis Request').first().json;
const claudeResponse = $input.first().json;

const noteText = (claudeResponse.content && claudeResponse.content[0] && claudeResponse.content[0].text && claudeResponse.content[0].text.trim())
  || "Automated enrichment failed to produce a note for this lead \u2014 manual research needed before the call.";

return [{
  json: {
    contactId: lead.contactId,
    noteText,
  },
}];
